#!/usr/bin/env python3
"""Zororo Phumulani v10.1 - TC validation fix"""
import os, base64, pathlib
DEST = pathlib.Path(os.path.dirname(os.path.abspath(__file__)))
FILES = {
    'main.py': '',
    'templates/index.html': '',
    'templates/admin.html': '',
    'static/app.js': '',
    'admin_dashboard.py': '',
    'requirements.txt': 'ZmFzdGFwaT09MC4xMDQuMQp1dmljb3JuW3N0YW5kYXJkXT09MC4yNC4wCnB5dGhvbi1tdWx0aXBhcnQ9PTAuMC42CnB5ZGFudGljW2VtYWlsXT09Mi41LjAKcmVwb3J0bGFiPT00LjAuNwpodHRweD09MC4yNC4xCg==',
}
def write(rel, b64):
    dest = DEST / rel
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(b64))
    print(f"  ok  {rel}  ({dest.stat().st_size:,} bytes)")
def main():
    print("\nZororo Phumulani — Installer v10.1 (TC fix)\n")
    for rel, b64 in FILES.items():
        write(rel, b64)
    print("\nDone. git add -A && git commit -m v10.1 && git push origin main")
if __name__ == "__main__":
    main()
